# ========================================
# CVMS Supplementary Analyses
# ========================================
# Computes supplementary metrics and tables on the 1,268-case
# consensus cohort using prediction files generated by ablation.py:
#   A. Per-model accuracy, Cohen's kappa, quadratic-weighted kappa, balanced
#      accuracy, macro-F1, and 2,000-bootstrap 95% CIs.
#   B. Canonical ablation table with bootstrap 95% CIs & paired differences
#      (Table III: Age + morphology, Morphology only, Age only).
#   C. Fine-to-coarse comparison (6-stage and 5-stage predictions collapsed into
#      3 growth phases vs. direct 3-stage models) with exact paired McNemar tests.
#   D. Within-phase vs. cross-phase error decomposition and +/-1-stage accuracy.
#   E. Age-atypical subgroup analysis (|age z-score| > 1 SD within phase) with
#      bootstrap 95% CIs & paired differences (Table IV).
#   F. Feature-selection stability over 100 bootstrap re-fits using train-only
#      scaling (--run-stability).
#   G. Leave-one-rater-out human benchmark and pairwise inter-rater agreement
#      using anonymized rater columns (Rater_1, Rater_2, Rater_3).
#
# Usage:
#   python supplementary_analyses.py [data.csv] [pred_dir] [out_dir] [--run-stability]

import argparse
import os

import numpy as np
import pandas as pd
from scipy.stats import binomtest
from sklearn.ensemble import RandomForestClassifier
from sklearn.metrics import (
    accuracy_score,
    balanced_accuracy_score,
    cohen_kappa_score,
    f1_score,
)
from sklearn.model_selection import train_test_split
from sklearn.preprocessing import StandardScaler
from statsmodels.stats.contingency_tables import mcnemar

SPLIT_SEED = 7
TEST_SIZE = 0.3
BOOT_SEED = 2026
N_BOOT = 2000
MODELS = ["SVM", "RForest", "LogReg", "MLP"]
RATER_COLS = ["Rater_1", "Rater_2", "Rater_3"]
FMT = {"Three_Class": "3-stage", "Five_Class": "5-stage", "Six_Class": "6-stage"}

ENC = {
    "Six_Class": lambda s: s.str.extract(r"(\d)$")[0].astype(int),
    "Five_Class": lambda s: s.map({
        "Class_1&2": 1, "Class_3": 2, "Class_4": 3, "Class_5": 4, "Class_6": 5
    }),
    "Three_Class": lambda s: s.map({
        "Pre-pubertal": 0, "Pubertal": 1, "Post-pubertal": 2
    }),
}
TO_THREE = {
    "Six_Class": lambda y: np.select([y <= 2, y <= 4], [0, 1], 2),
    "Five_Class": lambda y: np.select([y <= 1, y <= 3], [0, 1], 2),
    "Three_Class": lambda y: y,
}


def load_predictions(pred_dir, cfg, lab):
    path = os.path.join(pred_dir, f"pred_{cfg}_{lab}.csv")
    if not os.path.exists(path):
        return None
    p = pd.read_csv(path)
    out = {"idx": p["idx"].values, "y": ENC[lab](p["y"]).values}
    for m in MODELS:
        if m in p.columns:
            out[m] = ENC[lab](p[m]).values
    return out


def bootstrap_ci(rng, y, p, fn, n_boot=N_BOOT):
    n = len(y)
    vals = [fn(y[b], p[b]) for b in (rng.integers(0, n, n) for _ in range(n_boot))]
    return np.percentile(vals, [2.5, 97.5])


def run_stability(df, out_dir, n_boot=100):
    """100-bootstrap RF feature-selection stability using train-only scaling."""
    start = list(df.columns).index("Gender")
    feats = list(df.columns[start:start + 51])
    Xraw = df[feats].replace([np.inf, -np.inf], 0)
    rng = np.random.default_rng(0)
    out = {}
    for lab in ["Three_Class", "Five_Class", "Six_Class"]:
        Xtr0, _, ytr, _ = train_test_split(Xraw, df[lab], test_size=TEST_SIZE, random_state=SPLIT_SEED)
        sc = StandardScaler().fit(Xtr0)
        Xtr = pd.DataFrame(sc.transform(Xtr0), columns=feats, index=Xtr0.index).fillna(0)
        cnt = pd.Series(0, index=feats, dtype=float)
        for b in range(n_boot):
            idx = rng.integers(0, len(ytr), len(ytr))
            rf = RandomForestClassifier(n_estimators=1000, random_state=b, n_jobs=-1)
            rf.fit(Xtr.iloc[idx], ytr.iloc[idx])
            cnt += (rf.feature_importances_ > 0.015)
        out[lab] = cnt / n_boot
        print(f"Bootstrap feature-selection stability complete: {lab}", flush=True)
    F = pd.DataFrame(out)
    F.to_csv(os.path.join(out_dir, "F_stability.csv"))
    return F


def compute_table_iii(preds, out_dir):
    """Reproduce Table III: canonical ablation accuracies and paired differences (95% bootstrap CI)."""
    arms_map = {"Age + morphology": "all", "Morphology only": "noage", "Age only": "age"}
    contrasts = [
        ("Age + morphology", "Morphology only"),
        ("Age + morphology", "Age only"),
        ("Morphology only", "Age only"),
    ]
    rows, paired = [], []
    for lab, fmt_name in FMT.items():
        if not all((cfg, lab) in preds for cfg in arms_map.values()):
            continue
        y = preds[("all", lab)]["y"]
        n = len(y)
        idx = np.random.default_rng(BOOT_SEED).integers(0, n, size=(N_BOOT, n))
        C = {
            arm_label: np.column_stack([(preds[(cfg, lab)][m] == y) for m in MODELS])
            for arm_label, cfg in arms_map.items()
        }
        for arm_label in arms_map:
            c = C[arm_label].mean(axis=1)
            draws = np.array([c[b].mean() for b in idx])
            lo, hi = np.percentile(draws, [2.5, 97.5])
            rows.append(dict(format=fmt_name, arm=arm_label, acc=c.mean() * 100, lo=lo * 100, hi=hi * 100))
        for A, B in contrasts:
            ma, mb = C[A].mean(axis=1), C[B].mean(axis=1)
            draws = np.array([ma[b].mean() - mb[b].mean() for b in idx])
            lo, hi = np.percentile(draws, [2.5, 97.5])
            ps = []
            for j in range(len(MODELS)):
                a_only = int((C[A][:, j] & ~C[B][:, j]).sum())
                b_only = int((~C[A][:, j] & C[B][:, j]).sum())
                ps.append(1.0 if a_only + b_only == 0 else binomtest(a_only, a_only + b_only, 0.5).pvalue)
            paired.append(dict(
                format=fmt_name,
                contrast=f"{A} minus {B}",
                diff=(ma.mean() - mb.mean()) * 100,
                lo=lo * 100,
                hi=hi * 100,
                mcnemar_p_by_model="/".join(f"{p:.3f}" for p in ps),
            ))
    if rows:
        R = pd.DataFrame(rows).round(1)
        Pd = pd.DataFrame(paired).round(1)
        R.to_csv(os.path.join(out_dir, "TableIII_ablation_arms.csv"), index=False)
        Pd.to_csv(os.path.join(out_dir, "TableIII_ablation_paired.csv"), index=False)
        print("\n=== Table III. Canonical ablation (mean & 95% CI) ===")
        print(R.to_string(index=False))
        print(Pd.to_string(index=False))


def compute_table_iv(d, idx_tr, idx_te, preds, out_dir):
    """Reproduce Table IV: 3-stage test accuracy stratified by typical/atypical age (95% CI)."""
    arms_map = {"Age + morphology": "all", "Morphology only": "noage", "Age only": "age"}
    if not all((cfg, "Three_Class") in preds for cfg in arms_map.values()):
        return
    age = d["Age month"].values.astype(float)
    ph = TO_THREE["Six_Class"](ENC["Six_Class"](d["Six_Class"]).values)
    mu = {k: age[idx_tr][ph[idx_tr] == k].mean() for k in range(3)}
    sd = {k: age[idx_tr][ph[idx_tr] == k].std(ddof=1) for k in range(3)}
    z = np.array([(age[i] - mu[ph[i]]) / sd[ph[i]] for i in idx_te])

    groups = {
        "Typical age": np.abs(z) <= 1.0,
        "Atypical age": np.abs(z) > 1.0,
        "Early maturers": z < -1.0,
        "Late maturers": z > 1.0,
    }
    contrasts = [
        ("Age + morphology", "Morphology only"),
        ("Morphology only", "Age only"),
    ]
    y = preds[("all", "Three_Class")]["y"]
    C_full = {
        arm_label: np.column_stack([(preds[(cfg, "Three_Class")][m] == y) for m in MODELS])
        for arm_label, cfg in arms_map.items()
    }

    arm_rows, pair_rows = [], []
    for gname, mask in groups.items():
        n = int(mask.sum())
        idx = np.random.default_rng(BOOT_SEED).integers(0, n, size=(N_BOOT, n))
        for arm_label in arms_map:
            c = C_full[arm_label][mask].mean(axis=1)
            draws = np.array([c[b].mean() for b in idx])
            lo, hi = np.percentile(draws, [2.5, 97.5])
            arm_rows.append(dict(group=gname, n=n, arm=arm_label, acc=c.mean() * 100, lo=lo * 100, hi=hi * 100))
        for A, B in contrasts:
            ma = C_full[A][mask].mean(axis=1)
            mb = C_full[B][mask].mean(axis=1)
            draws = np.array([ma[b].mean() - mb[b].mean() for b in idx])
            lo, hi = np.percentile(draws, [2.5, 97.5])
            pair_rows.append(dict(
                group=gname,
                n=n,
                contrast=f"{A} minus {B}",
                diff=(ma.mean() - mb.mean()) * 100,
                lo=lo * 100,
                hi=hi * 100,
            ))
    R = pd.DataFrame(arm_rows).round(1)
    Pd = pd.DataFrame(pair_rows).round(1)
    R.to_csv(os.path.join(out_dir, "TableIV_age_atypical_arms.csv"), index=False)
    Pd.to_csv(os.path.join(out_dir, "TableIV_age_atypical_paired.csv"), index=False)
    print("\n=== Table IV. 3-stage age-atypical subgroup (mean & 95% CI) ===")
    print(R.to_string(index=False))
    print(Pd.to_string(index=False))


def main():
    script_dir = os.path.dirname(os.path.abspath(__file__))
    default_csv = os.path.join(script_dir, "project2_CVMS.csv")

    parser = argparse.ArgumentParser(description="Run CVMS supplementary analyses.")
    parser.add_argument("data_csv", nargs="?", default=default_csv)
    parser.add_argument("pred_dir", nargs="?", default="ablation_out")
    parser.add_argument("out_dir", nargs="?", default="supplementary_out")
    parser.add_argument("--run-stability", action="store_true", help="Run 100-bootstrap RF feature-selection stability")
    args = parser.parse_args()

    os.makedirs(args.out_dir, exist_ok=True)
    rng = np.random.default_rng(BOOT_SEED)

    d = pd.read_csv(args.data_csv)
    if "Level of dentists agreement" in d.columns:
        d = d[d["Level of dentists agreement"] != "Disagreement"].reset_index(drop=True)

    idx_tr, idx_te = train_test_split(np.arange(len(d)), test_size=TEST_SIZE, random_state=SPLIT_SEED)

    # A. Per-model metrics + 95% bootstrap CIs
    rows, preds = [], {}
    for cfg in ["all", "noage", "morph", "age"]:
        for lab in FMT:
            L = load_predictions(args.pred_dir, cfg, lab)
            if L is None:
                continue
            preds[(cfg, lab)] = L
            assert (L["idx"] == idx_te).all(), f"Test indices mismatch for {cfg}/{lab}"
            for m in MODELS:
                if m not in L:
                    continue
                y, p = L["y"], L[m]
                r = dict(
                    config=cfg,
                    format=FMT[lab],
                    model=m,
                    acc=accuracy_score(y, p),
                    kappa=cohen_kappa_score(y, p),
                    qwk=cohen_kappa_score(y, p, weights="quadratic"),
                    bal_acc=balanced_accuracy_score(y, p),
                    macroF1=f1_score(y, p, average="macro"),
                )
                if cfg == "all":
                    r["acc_lo"], r["acc_hi"] = bootstrap_ci(rng, y, p, accuracy_score)
                    r["kappa_lo"], r["kappa_hi"] = bootstrap_ci(rng, y, p, cohen_kappa_score)
                if lab != "Three_Class":
                    y3, p3 = TO_THREE[lab](y), TO_THREE[lab](p)
                    r["collapsed3_acc"] = accuracy_score(y3, p3)
                    r["collapsed3_kappa"] = cohen_kappa_score(y3, p3)
                rows.append(r)

    if rows:
        R = pd.DataFrame(rows)
        R.to_csv(os.path.join(args.out_dir, "A_metrics_per_model.csv"), index=False)
        print("=== A. Mean over models ===")
        print(R.groupby(["config", "format"]).mean(numeric_only=True).round(4))

    # B. Table III (canonical ablation CIs)
    compute_table_iii(preds, args.out_dir)

    # C. Fine-to-coarse McNemar comparison
    L3 = preds.get(("all", "Three_Class"))
    L5 = preds.get(("all", "Five_Class"))
    L6 = preds.get(("all", "Six_Class"))
    if L3 and L6:
        y3 = L3["y"]
        c_rows = []
        for m in MODELS:
            if m not in L3 or m not in L6:
                continue
            a = L3[m] == y3
            b = TO_THREE["Six_Class"](L6[m]) == y3
            table = [[int(np.sum(a & b)), int(np.sum(a & ~b))], [int(np.sum(~a & b)), int(np.sum(~a & ~b))]]
            r = dict(
                model=m,
                direct3=float(a.mean()),
                collapsed6to3=float(b.mean()),
                direct_only=table[0][1],
                collapsed_only=table[1][0],
                p=float(mcnemar(table, exact=True).pvalue),
            )
            if L5 and m in L5:
                r["collapsed5to3"] = float((TO_THREE["Five_Class"](L5[m]) == y3).mean())
            c_rows.append(r)
        C = pd.DataFrame(c_rows)
        C.to_csv(os.path.join(args.out_dir, "C_fine_to_coarse.csv"), index=False)
        print("\n=== C. Direct 3-stage vs collapsed ===")
        print(C.round(4))

    # D. Error decomposition
    for lab in ["Six_Class", "Five_Class"]:
        L = preds.get(("all", lab))
        if not L:
            continue
        d_rows = []
        for m in MODELS:
            if m not in L:
                continue
            y, p = L["y"], L[m]
            err = y != p
            cross = TO_THREE[lab](y) != TO_THREE[lab](p)
            d_rows.append(dict(
                model=m,
                exact=float(1 - err.mean()),
                within_phase_err=float((err & ~cross).mean()),
                cross_phase_err=float(cross.mean()),
                share_within=float((err & ~cross).sum() / err.sum()) if err.sum() else np.nan,
                within1=float((np.abs(y - p) <= 1).mean()),
                cross_gt1=float((np.abs(y - p) > 1).mean()),
            ))
        D = pd.DataFrame(d_rows)
        D.to_csv(os.path.join(args.out_dir, f"D_errors_{lab}.csv"), index=False)
        print(f"\n=== D. {FMT[lab]} error decomposition ===")
        print(D.round(4))

    # E. Table IV (age-atypical subgroup CIs)
    compute_table_iv(d, idx_tr, idx_te, preds, args.out_dir)

    # G. Human benchmark (leave-one-rater-out + pairwise inter-rater on consensus cohort)
    if all(c in d.columns for c in RATER_COLS):
        if L6 and L3:
            loo_rows = []
            for r in RATER_COLS:
                others = [x for x in RATER_COLS if x != r]
                a = d[others[0]].values[idx_te]
                b = d[others[1]].values[idx_te]
                me = d[r].values[idx_te]
                agree = a == b
                ref6 = a[agree]
                ref3 = TO_THREE["Six_Class"](ref6)
                loo_rows.append(dict(
                    rater=r,
                    n=int(agree.sum()),
                    rater_acc6=float(np.mean(me[agree] == ref6)),
                    rater_k6=float(cohen_kappa_score(ref6, me[agree])),
                    model_acc6=float(np.mean([np.mean(L6[m][agree] == ref6) for m in MODELS if m in L6])),
                    model_k6=float(np.mean([cohen_kappa_score(ref6, L6[m][agree]) for m in MODELS if m in L6])),
                    rater_acc3=float(np.mean(TO_THREE["Six_Class"](me[agree]) == ref3)),
                    rater_k3=float(cohen_kappa_score(ref3, TO_THREE["Six_Class"](me[agree]))),
                    model_acc3_direct=float(np.mean([np.mean(L3[m][agree] == ref3) for m in MODELS if m in L3])),
                    model_k3_direct=float(np.mean([cohen_kappa_score(ref3, L3[m][agree]) for m in MODELS if m in L3])),
                ))
            LOO = pd.DataFrame(loo_rows)
            LOO.to_csv(os.path.join(args.out_dir, "G_leave_one_rater_out.csv"), index=False)
            print("\n=== G. Leave-one-rater-out benchmark ===")
            print(LOO.round(3))

        pair_rows = []
        for i in range(len(RATER_COLS)):
            for j in range(i + 1, len(RATER_COLS)):
                a, b = d[RATER_COLS[i]].values, d[RATER_COLS[j]].values
                pair_rows.append(dict(
                    pair=f"{RATER_COLS[i]}-{RATER_COLS[j]}",
                    n=len(d),
                    acc6=float(np.mean(a == b)),
                    k6=float(cohen_kappa_score(a, b)),
                    wk6=float(cohen_kappa_score(a, b, weights="linear")),
                    acc3=float(np.mean(TO_THREE["Six_Class"](a) == TO_THREE["Six_Class"](b))),
                    k3=float(cohen_kappa_score(TO_THREE["Six_Class"](a), TO_THREE["Six_Class"](b))),
                ))
        G = pd.DataFrame(pair_rows)
        G.to_csv(os.path.join(args.out_dir, "G_interrater_consensus.csv"), index=False)
        print("\n=== G. Pairwise inter-rater (1,268 consensus cases) ===")
        print(G.round(3))

    # F. Optional 100-bootstrap feature-selection stability
    if args.run_stability:
        run_stability(d, args.out_dir)


if __name__ == "__main__":
    main()
